css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-pc{width:min(1000px,100%)}
.fx-pc .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6em}
.fx-pc .card{display:flex;flex-direction:column;gap:.9em}
.fx-pc .media{position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;background:color-mix(in srgb,var(--surface) 94%,var(--text))}
.fx-pc .media .fx-art{position:absolute;inset:0;transition:opacity calc(.5s/var(--speed)),transform calc(.8s/var(--speed)) cubic-bezier(.2,.8,.2,1)}
.fx-pc .media .alt{opacity:0;transform:scale(1.06)}
.fx-pc .card:hover .alt,.fx-pc .card:focus-within .alt{opacity:1;transform:none}
.fx-pc .card:hover .media>.fx-art:first-child{transform:scale(1.05)}
.fx-pc .bd{position:absolute;left:.8em;top:.8em;padding:.3em .7em;border-radius:99px;background:var(--surface);color:var(--text);font:700 .7em var(--font-body);letter-spacing:.1em;text-transform:uppercase;z-index:2}
.fx-pc .bd.sale{background:var(--accent);color:var(--on-accent)}
.fx-pc .wish{position:absolute;right:.7em;top:.7em;z-index:2;width:2.4em;height:2.4em;border-radius:50%;background:var(--surface);display:grid;place-items:center;cursor:pointer;box-shadow:0 4px 12px -4px rgba(0,0,0,.35)}
.fx-pc .wish input{position:absolute;inset:0;opacity:0;margin:0;cursor:pointer}
.fx-pc .wish svg{width:1.15em;height:1.15em;fill:transparent;stroke:var(--text);stroke-width:1.8;stroke-linejoin:round;transition:fill .25s,stroke .25s,transform calc(.35s/var(--speed)) cubic-bezier(.3,1.8,.5,1)}
.fx-pc .wish input:checked+svg{fill:var(--accent);stroke:var(--accent);transform:scale(1.18)}
.fx-pc .wish:has(input:focus-visible){outline:2px solid var(--accent);outline-offset:2px}
.fx-pc .add{position:absolute;left:.7em;right:.7em;bottom:.7em;z-index:2;display:flex;justify-content:center;align-items:center;gap:.5em;padding:.8em;border:0;border-radius:calc(var(--radius) - 2px);background:var(--primary);color:var(--on-primary);font:700 .88em var(--font-body);cursor:pointer;transform:translateY(calc(100% + 1em));transition:transform calc(.4s/var(--speed)) cubic-bezier(.2,.8,.2,1),background .2s}
.fx-pc .add svg{width:1.2em;height:1.2em;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linejoin:round}
.fx-pc .card:hover .add,.fx-pc .card:focus-within .add{transform:none}
.fx-pc .add:hover{background:color-mix(in srgb,var(--primary) 82%,var(--accent))}
.fx-pc .add:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.fx-pc .top{display:flex;justify-content:space-between;gap:1em;align-items:start}
.fx-pc .top small{font-size:.74em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;opacity:.55}
.fx-pc .top h3{font-size:1.15em;margin-top:.15em}
.fx-pc .pr{font-weight:700;white-space:nowrap}.fx-pc .pr s{font-weight:400;opacity:.5;margin-left:.45em;font-size:.9em}
.fx-pc .sw{display:flex;gap:.45em;margin-top:.55em}.fx-pc .sw i{width:.95em;height:.95em;border-radius:50%;background:var(--c);box-shadow:0 0 0 1px var(--border),inset 0 0 0 2px var(--surface)}
@media(hover:none){.fx-pc .add{transform:none;left:auto;padding:.6em .9em}}
@media(max-width:760px){.fx-pc .grid{grid-template-columns:1fr 1fr}.fx-pc .card:nth-child(3){display:none}}
@media(max-width:420px){.fx-pc .grid{grid-template-columns:1fr}.fx-pc .card:nth-child(2){display:none}}
@media(prefers-reduced-motion:reduce){.fx-pc .media .fx-art,.fx-pc .add,.fx-pc .wish svg{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-pc .card.is-tap .alt{opacity:1;transform:none}
.fx-pc .card.is-tap .media>.fx-art:first-child{transform:scale(1.05)}
.fx-pc .card.is-tap .add{transform:none}
.fx-pc .add.is-tap{background:color-mix(in srgb,var(--primary) 82%,var(--accent))}
